def transform(grid):
    # Keep the bottom pattern and the top candidate with the greatest
    # geometric correspondence to it; stack them below the divider.
    h, w = len(grid), len(grid[0])
    divider = next(r for r in range(h) if all(v == 5 for v in grid[r]))
    objects = {}
    for r in range(divider):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 5):
                objects.setdefault(v, []).append((r, c))
    bottom = [(r, c) for r in range(divider + 1, h) for c in range(w) if grid[r][c] == 1]
    def norm(points):
        mr = min(r for r, c in points)
        mc = min(c for r, c in points)
        return {(r-mr, c-mc) for r, c in points}
    target = norm(bottom)
    candidates = []
    for color, pts in objects.items():
        p = norm(pts)
        # Compare all rotations/reflections and favor the closest-sized shape.
        variants = []
        for flip in (False, True):
            for k in range(4):
                q = {(c, -r if flip else r) for r, c in p}
                for _ in range(k):
                    q = {(c, -r) for r, c in q}
                variants.append(norm(list(q)))
        score = max(len(target & q) for q in variants) - abs(len(target)-len(p))
        candidates.append((score, color, pts))
    color, pts = max(candidates, key=lambda x: x[0])[1:]
    selected = norm(pts)
    target = norm(bottom)
    out = [[0]*w for _ in range(9)]
    for r, c in selected:
        out[2+r][5+c] = color
    for r, c in target:
        out[5+r][5+c] = 1
    return out
